SMW_ITEMS = []
for idx, (title, lead, correct, wrong, why) in enumerate(SMW_RAW, 1):
    assert len(wrong) == 3, f"SMW {idx}: need three wrong endings"
    slot = (idx - 1) % 4
    texts = wrong[:slot] + [correct] + wrong[slot:]
    letters = "ABCD"
    SMW_ITEMS.append({
        "id": f"q-pl90-smw-{idx:02d}",
        "type_id": "pte-select-missing-word",
        "type_name": "Select Missing Word",
        "title": title,
        "prompt": "You will hear a recording. At the end of the recording the last word or group of words has been replaced by a beep. Select the correct option to complete the recording.",
        "audio_transcript": f"{lead} [beep]",
        "prep_time_seconds": 7,
        "time_limit_seconds": 90,
        "options": [{"id": letters[n], "text": t} for n, t in enumerate(texts)],
        "correct_answers": [letters[slot]],
        "blanks": None,
        "model_answer": None,
        "explanation": f"Option ({letters[slot]}) is correct: the recording ends with \"{correct}\". {why}",
        "points": 1,
    })
